import json, subprocess, sys
data=open('/app/tmp/t/fuzz_lines.jsonl','rb').read()
p=subprocess.run([sys.executable,"-I","/app/submission/main.py"],input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=90)
out=p.stdout.decode()
lines=out.split("\n")
print("stderr:", p.stderr.decode(errors="replace")[:400])
print("returncode",p.returncode)
cnt=0
for i,l in enumerate(lines):
    if l=="":
        print("empty line at", i); continue
    try:
        d=json.loads(l)
        assert set(d.keys()) in ({"error"},) or all(k in ("op","hosts","floor","slots","packets","events","safe","safety","terminates","liveness","module","config") for k in d.keys())
        cnt+=1
    except Exception as e:
        print("BAD", i, l[:100], e)
print("parsed", cnt, "of", len(lines)-1)
cats={}
for l in lines:
    if l.strip():
        d=json.loads(l)
        v=d.get("error")
        cats[v]=cats.get(v,0)+1
print(cats)
